def criar_pilha(cap):
    return {"cap": cap, "itens": []}

def push(pilha, valor):
    if len(pilha["itens"]) == pilha["cap"]:
        return False
    pilha["itens"].append(valor)
    return True

def pop(pilha):
    if not pilha["itens"]:
        return None
    return pilha["itens"].pop()

p = criar_pilha(2)
print(push(p, 10), push(p, 5), push(p, 99))
print(pop(p), pop(p), pop(p))

def delimitadores_validos(expr):
    pares = {")": "(", "]": "["}
    pilha = []
    for ch in expr:
        if ch in "([":
            pilha.append(ch)
        elif ch in ")]":
            if not pilha or pilha.pop() != pares[ch]:
                return False
    return len(pilha) == 0

print(delimitadores_validos("([a+b])"), delimitadores_validos("([)]"), delimitadores_validos("(()"))

