def criar_fila(cap):
    return {"cap": cap, "dados": [None] * cap, "rpos": 0, "spos": 0, "qtd": 0}

def push_seguro(fila, valor):
    if fila["qtd"] == fila["cap"]:
        return "Fila Cheia!!"
    fila["dados"][fila["spos"]] = valor
    fila["spos"] = (fila["spos"] + 1) % fila["cap"]
    fila["qtd"] += 1
    return "OK"

f = {"cap": 3, "dados": [None, 20, 30], "rpos": 1, "spos": 0, "qtd": 2}
print(push_seguro(f, 40))
print(push_seguro(f, 50))

