def checa(s):
    par = {")": "(", "]": "["}
    st = []
    for c in s:
        if c in "([": st.append(c)
        elif c in ")]":
            if not st or st.pop() != par[c]: return False
    return not st

print(checa("(a)"), checa(")("), checa("[()]"))
